public class LibraryMemberBean {private String membershipId,securityAnswer,name;private boolean premium;public LibraryMemberBean(){}public String getMembershipId(){return membershipId;}public void setMembershipId(String id){if(membershipId==null)membershipId=id;}public String getName(){return name;}public void setName(String n){name=n;}public boolean isPremium(){return premium;}public void setPremium(boolean p){premium=p;}public void setSecurityAnswer(String s){securityAnswer=Integer.toString(s.hashCode());}public static void main(String[]a){LibraryMemberBean m=new LibraryMemberBean();m.setMembershipId("M1");System.out.println(m.getMembershipId());}}
